// Supabase has emitted both UUIDs and opaque lowercase authorization handles.
// Keep the value URL-safe and bounded without assuming one server-side format.
export const authorizationIdPattern = /^[A-Za-z0-9_-]{20,512}$/;

export const readAuthorizationId = (parameters: URLSearchParams) => {
  const values = parameters.getAll('authorization_id');
  if (values.length !== 1) return null;
  const value = values[0]?.trim() || '';
  return authorizationIdPattern.test(value) ? value : null;
};

type OAuthAuthorizationBinding = {
  authorization_id: string;
  user: { id: string };
  client: { id: string };
};

export const isBoundOAuthAuthorization = (
  value: unknown,
  expected: { authorizationId: string; userId: string; clientId: string },
): value is OAuthAuthorizationBinding => {
  if (!value || typeof value !== 'object') return false;
  const candidate = value as Partial<OAuthAuthorizationBinding>;
  return candidate.authorization_id === expected.authorizationId
    && candidate.user?.id === expected.userId
    && candidate.client?.id === expected.clientId;
};

export const hasOAuthGrantForClient = (value: unknown, clientId: string) => (
  Array.isArray(value)
  && value.some((grant) => grant
    && typeof grant === 'object'
    && (grant as { client?: { id?: unknown } }).client?.id === clientId)
);

export const hasCurrentMcpConsentDecision = (value: unknown, clientId: string) => {
  if (!value || typeof value !== 'object') return false;
  const summary = value as {
    oauth_client_id?: unknown;
    data_access_mode?: unknown;
    connection_status?: unknown;
    consented_at?: unknown;
    connection_review_version?: unknown;
    current_review_version?: unknown;
    is_ready?: unknown;
  };
  const currentReview = typeof summary.current_review_version === 'number'
    && Number.isSafeInteger(summary.current_review_version)
    && summary.current_review_version > 0
    && summary.connection_review_version === summary.current_review_version;
  if (summary.oauth_client_id !== clientId
    || summary.data_access_mode !== 'mcp_scoped'
    || !currentReview
    || typeof summary.consented_at !== 'string'
    || !summary.consented_at) return false;
  return summary.connection_status === 'denied'
    || (summary.connection_status === 'active' && summary.is_ready === true);
};

export const normalizeSafeOAuthUrl = (value: string) => {
  if (!value || value.length > 2048 || value.includes('*') || /[\u0000-\u0020\u007f]/.test(value)) return null;
  try {
    const url = new URL(value);
    const loopback = url.hostname === 'localhost' || url.hostname === '[::1]'
      || /^127(?:\.\d{1,3}){3}$/.test(url.hostname);
    if (!url.hostname || url.username || url.password || url.hash
      || (url.protocol !== 'https:' && !(url.protocol === 'http:' && loopback))) return null;
    return url;
  } catch {
    return null;
  }
};

export const isSafeOAuthResult = (resultUrl: string, registeredRedirect?: string) => {
  const result = normalizeSafeOAuthUrl(resultUrl);
  if (!result || result.searchParams.has('code') === result.searchParams.has('error')) return false;
  const resultOnlyParameters = new Set(['code', 'error', 'error_description', 'error_uri', 'state']);
  for (const key of resultOnlyParameters) {
    if (result.searchParams.getAll(key).length > 1) return false;
  }
  if (!registeredRedirect) return true;

  const registered = normalizeSafeOAuthUrl(registeredRedirect);
  if (!registered || result.origin !== registered.origin || result.pathname !== registered.pathname) return false;
  const baseParameters = new URLSearchParams(result.searchParams);
  for (const key of resultOnlyParameters) baseParameters.delete(key);
  return baseParameters.toString() === registered.searchParams.toString();
};
